def read_number(n: int) -> str:
    if n == 0:
        return '영'

    digits = ['', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']

    def read_group(num):
        """Read a group of 4 digits (0-9999)"""
        if num == 0:
            return ''

        result = ''

        # 천 (thousands)
        if num >= 1000:
            thousands = num // 1000
            if thousands != 1:
                result += digits[thousands]
            result += '천'

        # 백 (hundreds)
        remainder = num % 1000
        if remainder >= 100:
            hundreds = remainder // 100
            if hundreds != 1:
                result += digits[hundreds]
            result += '백'

        # 십 (tens)
        remainder = num % 100
        if remainder >= 10:
            tens = remainder // 10
            if tens != 1:
                result += digits[tens]
            result += '십'

        # 일 (ones)
        ones = num % 10
        if ones > 0:
            result += digits[ones]

        return result

    # Split into groups: ones, 만, 억
    ones_group = n % 10000
    man_group = (n // 10000) % 10000
    eok_group = (n // 100000000) % 10000

    result = ''

    # 억 group
    if eok_group > 0:
        result += read_group(eok_group) + '억'

    # 만 group
    if man_group > 0:
        if man_group == 1:
            result += '만'
        else:
            result += read_group(man_group) + '만'

    # ones group
    if ones_group > 0:
        result += read_group(ones_group)

    return result
